import sys
from collections import defaultdict

def count_awesome_substrings(s):
    n = len(s)
    prefix_count = defaultdict(int)
    prefix_count[0] = 1
    current_sum = 0
    result = 0

    for i in range(n):
        if s[i] == '1':
            current_sum += 1

        for j in range(1, current_sum + 1):
            if i + 1 >= j and (i + 1) % j == 0:
                result += prefix_count[current_sum - j]

        prefix_count[current_sum] += 1

    return result

def main():
    import sys
    s = sys.stdin.read().strip()
    print(count_awesome_substrings(s))

if __name__ == "__main__":
    main()
